def solve(I):
    R,C=len(I),len(I[0])
    two={(r,c) for r in range(R) for c in range(C) if I[r][c]==2}
    from collections import Counter
    cnt=Counter(v for row in I for v in row if v!=2)
    bg=cnt.most_common(1)[0][0]
    others=[(r,c,I[r][c]) for r in range(R) for c in range(C) if I[r][c] not in (2,bg)]
    out=[row[:] for row in I]
    hbar = len({r for r,_ in two})==1
    if hbar:
        bar_row=max(r for r,_ in two); sr={r for r,_,_ in others}
        if max(sr)<bar_row:
            shift=bar_row-max(sr)-1; fmin=min(sr)+shift; fmax=max(sr)+shift; edge=fmin-1
        else:
            shift=min(sr)-bar_row; fmin=min(sr)+shift; fmax=max(sr)+shift; edge=fmax+1
        for r,c,v in others: out[r+shift][c]=v
        for c in range(C): out[edge][c]=8
    else:
        bar_col=max(c for _,c in two); sc={c for _,c,_ in others}
        if max(sc)<bar_col:
            shift=bar_col-max(sc)-1; fmin=min(sc)+shift; fmax=max(sc)+shift; edge=fmin-1
        else:
            shift=min(sc)-bar_col; fmin=min(sc)+shift; fmax=max(sc)+shift; edge=fmax+1
        for r,c,v in others: out[r][c+shift]=v
        for r in range(R): out[r][edge]=8
    return out
