import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(I):
    R,C=len(I),len(I[0])
    two={(r,c) for r in range(R) for c in range(C) if I[r][c]==2}
    bg=Counter(v for row in I for v in row if v!=2).most_common(1)[0][0]
    shp={(r,c,I[r][c]) for r in range(R) for c in range(C) if I[r][c] not in (2,bg)}
    out=[row[:] for row in I]
    rs={r for r,_ in two}; cs={c for _,c in two}
    horiz = len(rs)==1   # horizontal bar -> move vertically
    def touching(cells,barline):
        # orthogonal adjacency to any bar cell
        for r,c,v in cells:
            if (r+1,c) in barline or (r-1,c) in barline or (r,c+1) in barline or (r,c-1) in barline: return True
        return False
    if horiz:
        bar=max(rs)
        sr=sorted({r for r,_,_ in shp})
        if not touching(shp, two):
            shift=bar-1-sr[-1] if sr[-1]<bar else bar+1-sr[0]
            for r,c,v in shp: out[r+shift][c]=v
        edge = max(sr)+ (bar-1-sr[-1]) +1 - (1 if sr[-1]<bar else 0)
        # edge: far side adjacent to shape
        edge = (max(sr)+(bar-1-sr[-1])+1) if sr[-1]<bar else (min(sr)+(bar+1-sr[0])-1)
        for c in range(C): out[edge][c]=8
    else:
        bar=max(cs)
        sc=sorted({c for _,c,_ in shp})
        if not touching(shp, two):
            shift=bar-1-sc[-1] if sc[-1]<bar else bar+1-sc[0]
            for r,c,v in shp: out[r][c+shift]=v
        edge = (max(sc)+(bar-1-sc[-1])+1) if sc[-1]<bar else (min(sc)+(bar+1-sc[0])-1)
        for r in range(R): out[r][edge]=8
    return out
